using Avalonia.Media;
using Material3Expressive.Avalonia.ColorSystem;
using Xunit;

namespace Material3Expressive.Avalonia.Tests;

public class ColorSchemeTests
{
    private static readonly Color BaselineSeed = Color.Parse("#6750A4");

    // Official Material 3 baseline tokens (seed #6750A4). Error roles use the palette generated by
    // material-color-utilities (hue 25, chroma 84); the spec's baseline error colors are hand-tuned.
    [Theory]
    [InlineData(nameof(Material3ColorScheme.Primary), "#6750A4")]
    [InlineData(nameof(Material3ColorScheme.OnPrimary), "#FFFFFF")]
    [InlineData(nameof(Material3ColorScheme.PrimaryContainer), "#EADDFF")]
    [InlineData(nameof(Material3ColorScheme.OnPrimaryContainer), "#21005D")]
    [InlineData(nameof(Material3ColorScheme.Secondary), "#625B71")]
    [InlineData(nameof(Material3ColorScheme.SecondaryContainer), "#E8DEF8")]
    [InlineData(nameof(Material3ColorScheme.OnSecondaryContainer), "#1D192B")]
    [InlineData(nameof(Material3ColorScheme.Tertiary), "#7D5260")]
    [InlineData(nameof(Material3ColorScheme.TertiaryContainer), "#FFD8E4")]
    [InlineData(nameof(Material3ColorScheme.Error), "#BA1A1A")]
    [InlineData(nameof(Material3ColorScheme.ErrorContainer), "#FFDAD6")]
    [InlineData(nameof(Material3ColorScheme.OnErrorContainer), "#410002")]
    [InlineData(nameof(Material3ColorScheme.Surface), "#FEF7FF")]
    [InlineData(nameof(Material3ColorScheme.OnSurface), "#1D1B20")]
    [InlineData(nameof(Material3ColorScheme.SurfaceVariant), "#E7E0EC")]
    [InlineData(nameof(Material3ColorScheme.OnSurfaceVariant), "#49454F")]
    [InlineData(nameof(Material3ColorScheme.SurfaceContainerLow), "#F7F2FA")]
    [InlineData(nameof(Material3ColorScheme.SurfaceContainer), "#F3EDF7")]
    [InlineData(nameof(Material3ColorScheme.SurfaceContainerHigh), "#ECE6F0")]
    [InlineData(nameof(Material3ColorScheme.SurfaceContainerHighest), "#E6E0E9")]
    [InlineData(nameof(Material3ColorScheme.Outline), "#79747E")]
    [InlineData(nameof(Material3ColorScheme.OutlineVariant), "#CAC4D0")]
    [InlineData(nameof(Material3ColorScheme.InverseSurface), "#322F35")]
    [InlineData(nameof(Material3ColorScheme.InversePrimary), "#D0BCFF")]
    public void Baseline_light_matches_material_tokens(string role, string expected)
    {
        var scheme = Material3ColorScheme.FromSeed(BaselineSeed, isDark: false, SchemeVariant.Baseline);
        AssertClose(Color.Parse(expected), RoleOf(scheme, role), role);
    }

    [Theory]
    [InlineData(nameof(Material3ColorScheme.Primary), "#D0BCFF")]
    [InlineData(nameof(Material3ColorScheme.OnPrimary), "#381E72")]
    [InlineData(nameof(Material3ColorScheme.PrimaryContainer), "#4F378B")]
    [InlineData(nameof(Material3ColorScheme.OnPrimaryContainer), "#EADDFF")]
    [InlineData(nameof(Material3ColorScheme.Secondary), "#CCC2DC")]
    [InlineData(nameof(Material3ColorScheme.Tertiary), "#EFB8C8")]
    [InlineData(nameof(Material3ColorScheme.Error), "#FFB4AB")]
    [InlineData(nameof(Material3ColorScheme.Surface), "#141218")]
    [InlineData(nameof(Material3ColorScheme.OnSurface), "#E6E0E9")]
    [InlineData(nameof(Material3ColorScheme.SurfaceContainer), "#211F26")]
    [InlineData(nameof(Material3ColorScheme.SurfaceContainerHigh), "#2B2930")]
    [InlineData(nameof(Material3ColorScheme.SurfaceContainerHighest), "#36343B")]
    [InlineData(nameof(Material3ColorScheme.Outline), "#938F99")]
    [InlineData(nameof(Material3ColorScheme.OutlineVariant), "#49454F")]
    public void Baseline_dark_matches_material_tokens(string role, string expected)
    {
        var scheme = Material3ColorScheme.FromSeed(BaselineSeed, isDark: true, SchemeVariant.Baseline);
        AssertClose(Color.Parse(expected), RoleOf(scheme, role), role);
    }

    [Theory]
    [InlineData("#6750A4")]
    [InlineData("#0061A4")]
    [InlineData("#B3261E")]
    [InlineData("#386A20")]
    public void Hct_round_trips_srgb_colors(string hex)
    {
        var color = Color.Parse(hex);
        var hct = Hct.FromColor(color);
        var back = Hct.From(hct.Hue, hct.Chroma, hct.Tone).ToColor();
        AssertClose(color, back, hex);
    }

    [Fact]
    public void Tonal_palette_tone_matches_requested_lstar()
    {
        var palette = TonalPalette.FromHueAndChroma(282, 48);
        foreach (var tone in new[] { 10, 30, 50, 70, 90 })
            Assert.InRange(Hct.FromColor(palette.Tone(tone)).Tone, tone - 0.6, tone + 0.6);
    }

    [Theory]
    [InlineData(SchemeVariant.TonalSpot)]
    [InlineData(SchemeVariant.Neutral)]
    [InlineData(SchemeVariant.Vibrant)]
    [InlineData(SchemeVariant.Expressive)]
    [InlineData(SchemeVariant.Monochrome)]
    public void Every_variant_keeps_text_contrast(SchemeVariant variant)
    {
        foreach (var dark in new[] { false, true })
        {
            var s = Material3ColorScheme.FromSeed(Color.Parse("#0061A4"), dark, variant);
            Assert.True(Contrast(s.OnSurface, s.Surface) >= 7, $"{variant} dark={dark} onSurface");
            Assert.True(Contrast(s.OnPrimary, s.Primary) >= 4.5, $"{variant} dark={dark} onPrimary");
            Assert.True(Contrast(s.OnPrimaryContainer, s.PrimaryContainer) >= 4.5, $"{variant} dark={dark} onPrimaryContainer");
        }
    }

    private static Color RoleOf(Material3ColorScheme scheme, string role) =>
        (Color)typeof(Material3ColorScheme).GetProperty(role)!.GetValue(scheme)!;

    private static void AssertClose(Color expected, Color actual, string what, int tolerance = 3)
    {
        var ok = Math.Abs(expected.R - actual.R) <= tolerance &&
                 Math.Abs(expected.G - actual.G) <= tolerance &&
                 Math.Abs(expected.B - actual.B) <= tolerance;
        Assert.True(ok, $"{what}: expected {expected}, got {actual}");
    }

    private static double Contrast(Color a, Color b)
    {
        static double Lum(Color c)
        {
            static double Ch(byte v)
            {
                var s = v / 255.0;
                return s <= 0.03928 ? s / 12.92 : Math.Pow((s + 0.055) / 1.055, 2.4);
            }

            return 0.2126 * Ch(c.R) + 0.7152 * Ch(c.G) + 0.0722 * Ch(c.B);
        }

        var (l1, l2) = (Lum(a), Lum(b));
        return (Math.Max(l1, l2) + 0.05) / (Math.Min(l1, l2) + 0.05);
    }
}
